reference_answer:
Use the runtime lifecycle: objects exist only from `beforeprojectstart`, logic runs on `tick`.

```js
// main.js (Purpose: Main script)
const SPEED = 200;

runOnStartup(async runtime => {
  runtime.addEventListener("beforeprojectstart", () => onBeforeProjectStart(runtime));
});

function onBeforeProjectStart(runtime) {
  runtime.addEventListener("tick", () => tick(runtime));
}

function tick(runtime) {
  const player = runtime.objects.Player.getFirstInstance();
  if (!player) return;
  const kb = runtime.keyboard;
  const step = SPEED * runtime.dt;
  if (kb.isKeyDown("ArrowLeft")) player.x -= step;
  if (kb.isKeyDown("ArrowRight")) player.x += step;
  if (kb.isKeyDown("ArrowUp")) player.y -= step;
  if (kb.isKeyDown("ArrowDown")) player.y += step;
}
```

