static SDL_Texture *make_score_texture(SDL_Renderer *renderer, TTF_Font *font, int score, float *w, float *h)
{
    char text[32];
    SDL_snprintf(text, sizeof(text), "Score: %d", score);
    SDL_Color white = { 255, 255, 255, 255 };
    SDL_Surface *surface = TTF_RenderText_Blended(font, text, 0, white);
    if (!surface) { SDL_Log("render text: %s", SDL_GetError()); return NULL; }
    SDL_Texture *tex = SDL_CreateTextureFromSurface(renderer, surface);
    *w = (float)surface->w;
    *h = (float)surface->h;
    SDL_DestroySurface(surface);
    return tex;
